package com.dentalcrm.common;
import com.dentalcrm.doctor.DoctorController; import com.dentalcrm.patient.PatientController; import com.dentalcrm.service.ClinicServiceController; import com.dentalcrm.settings.ClinicSettingsController; import org.junit.jupiter.api.Test; import org.springframework.security.access.prepost.PreAuthorize; import static org.junit.jupiter.api.Assertions.assertEquals;
class ManagementAuthorizationTest {@Test void managementMutationsAreAdminOnly() throws Exception {assertAdmin(DoctorController.class,"all");assertAdmin(DoctorController.class,"one",Long.class);assertAdmin(DoctorController.class,"create",com.dentalcrm.user.UserDtos.CreateDoctorUserRequest.class);assertAdmin(DoctorController.class,"update",Long.class,com.dentalcrm.doctor.DoctorDtos.UpdateDoctorRequest.class);assertAdmin(DoctorController.class,"active",Long.class,com.dentalcrm.doctor.DoctorDtos.DoctorActiveRequest.class);assertAdmin(DoctorController.class,"password",Long.class,com.dentalcrm.doctor.DoctorDtos.ResetPasswordRequest.class);assertAdmin(ClinicServiceController.class,"create",com.dentalcrm.service.ServiceDtos.ServiceRequest.class);assertAdmin(ClinicServiceController.class,"update",Long.class,com.dentalcrm.service.ServiceDtos.ServiceRequest.class);assertAdmin(PatientController.class,"update",Long.class,com.dentalcrm.patient.PatientDtos.PatientRequest.class);assertAdmin(ClinicSettingsController.class,"update",com.dentalcrm.settings.ClinicSettingsDtos.ClinicSettingsRequest.class);}private void assertAdmin(Class<?> type,String method,Class<?>...args)throws Exception{assertEquals("hasRole('ADMIN')",type.getMethod(method,args).getAnnotation(PreAuthorize.class).value());}}
